import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Assert;
import org.junit.Test;

import java.util.List;
import java.util.Map;

public class PropertyListBuilderTest {

    @Test
    public void addPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> propertyMock = Mockito.mock(Property.class);
        Mockito.when(propertyMock.getPath()).thenReturn("database.url");

        propertyListBuilder.add(propertyMock);
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();

        Assert.assertTrue(rootEntries.containsKey("database.url"));
    }

    @Test(expected = ConfigMeException.class)
    public void addNullPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        propertyListBuilder.add(null);
    }

    @Test
    public void createPropertyListHasElementsTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> propertyMock = Mockito.mock(Property.class);

        propertyListBuilder.add(propertyMock);
        List<Property<?>> propertyList = propertyListBuilder.create();

        Assert.assertEquals(1, propertyList.size());
    }

    @Test
    public void createEmptyPropertyListTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        List<Property<?>> propertyList = propertyListBuilder.create();

        Assert.assertEquals(0, propertyList.size());
    }

    @Test
    public void getRootEntriesWhenHasElementsTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> propertyMock = Mockito.mock(Property.class);
        Mockito.when(propertyMock.getPath()).thenReturn("database.url");

        propertyListBuilder.add(propertyMock);
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();

        Assert.assertEquals(1, rootEntries.size());
    }

    @Test
    public void getRootEntriesWhenEmptyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();

        Assert.assertEquals(0, rootEntries.size());
    }
}
